'use strict';
// GENERATED BY native-session-chat-split script — do not edit manually.
// Behavior-preserving extraction from native-session-chat.js.

const fs = require('node:fs');
const path = require('node:path');
const { readAccountCredentials } = require('./account-credential-store');
const {
  buildClaudeAccountRelayEnv,
  shouldRelayClaudeAccount
} = require('../cli/services/ai-cli/claude-account-relay');
const { buildAihServerProfileEnv } = require('../account/self-relay-account');
const { readServerConfig } = require('./server-config-store');
const { codexRelayProfile } = require('../cli/services/ai-cli/relay/codex-relay-profile');
const { readCodexGatewayConnection } = require('./codex-gateway-connection');
const {
  buildProviderRuntimeEnv,
  prepareProviderRuntime,
  resolveProviderRuntimeScope
} = require('../cli/services/ai-cli/provider-runtime-env');

function loadAccountEnv(aiHomeDir, accountRef) {
  try {
    const data = readAccountCredentials(fs, aiHomeDir, accountRef);
    return data && typeof data === 'object' ? data : {};
  } catch (_error) {
    return {};
  }
}


function loadProviderAccountEnv(provider, options = {}) {
  if (!options.gateway) return loadAccountEnv(options.aiHomeDir, options.accountRef);
  try {
    const serverConfig = readServerConfig({ fs, aiHomeDir: options.aiHomeDir });
    return buildAihServerProfileEnv(provider, serverConfig) || {};
  } catch (_error) {
    return {};
  }
}


function resolveNativeProviderRuntime(provider, projectionDir, baseEnv, options = {}) {
  const storedAccountEnv = options.accountEnv || loadProviderAccountEnv(provider, options);
  const authRelayed = shouldRelayClaudeAccount({
    provider,
    accountRef: options.accountRef,
    accountEnv: storedAccountEnv,
    gateway: options.gateway,
    isLogin: options.isLogin
  });
  let accountEnv = storedAccountEnv;
  if (codexRelayProfile.shouldRelayAccount({
    provider,
    accountRef: options.accountRef,
    accountEnv: storedAccountEnv,
    gateway: options.gateway,
    isLogin: options.isLogin
  })) {
    accountEnv = readCodexGatewayConnection(fs, options.aiHomeDir, options.accountRef).env;
  }
  if (authRelayed) {
    const serverConfig = readServerConfig({ fs, aiHomeDir: options.aiHomeDir });
    accountEnv = buildClaudeAccountRelayEnv(
      buildAihServerProfileEnv('claude', serverConfig),
      options.accountRef
    );
  }
  const scope = resolveProviderRuntimeScope(provider, projectionDir, baseEnv, {
    path,
    gateway: options.gateway === true,
    isLogin: options.isLogin === true,
    authRelayed,
    accountEnv
  });
  return { ...scope, accountEnv };
}


/**
 * gemini 账号库字段 → gemini CLI 实际读取的接入点变量。
 *
 * 账号库存的是 AIH 自己的键（GEMINI_BASE_URL；Vertex 账号另存 VERTEX_AI_PROJECT_ID /
 * VERTEX_AI_LOCATION），而 CLI 只认 GOOGLE_GEMINI_BASE_URL / GOOGLE_VERTEX_BASE_URL /
 * GOOGLE_GENAI_USE_VERTEXAI / GOOGLE_CLOUD_*。不映射的话账号配的接入点在启动时全部丢失。
 *
 * Vertex 账号的 base URL 指向任意实现了 Vertex generateContent 的宿主即可——包括 AIH 网关本身
 * （网关把 /v1[beta1]/[projects/../locations/..]/publishers/google/models/{m}:... 改写成标准
 * Gemini 入口，交给池里能处理 {m} 的账号；见 protocol-registry 的 VERTEX_GEMINI_PATH）。
 * 这样以后有了真正的 Gemini API Key / Vertex 账号，只换 base URL 与密钥即可无缝切换。
 */
function geminiCliEndpointEnv(accountEnv = {}) {
  const value = (key) => String(accountEnv[key] || '').trim();
  const env = {};
  const baseUrl = value('GEMINI_BASE_URL');
  const vertex = value('VERTEX_AI_PROJECT_ID') || value('VERTEX_AI_LOCATION')
    || value('GOOGLE_GENAI_USE_VERTEXAI').toLowerCase() === 'true';
  if (vertex) {
    env.GOOGLE_GENAI_USE_VERTEXAI = 'true';
    if (baseUrl) env.GOOGLE_VERTEX_BASE_URL = baseUrl;
    // express 模式（只给 API Key、不给项目）不能带项目/地域，否则 SDK 改走 ADC 认证。
    if (value('VERTEX_AI_PROJECT_ID') && value('VERTEX_AI_PLACEHOLDER') !== 'true') {
      env.GOOGLE_CLOUD_PROJECT = value('VERTEX_AI_PROJECT_ID');
      if (value('VERTEX_AI_LOCATION')) env.GOOGLE_CLOUD_LOCATION = value('VERTEX_AI_LOCATION');
    }
  } else if (baseUrl) {
    env.GOOGLE_GEMINI_BASE_URL = baseUrl;
  }
  return env;
}

function buildProviderEnv(provider, runtimeDir, baseEnv, options = {}) {
  const normalizedProvider = String(provider || '').toLowerCase();
  const extraEnv = {};
  if (normalizedProvider === 'gemini') {
    extraEnv.GEMINI_CLI_TRUST_WORKSPACE = 'true';
  }
  // Host credentials are stripped centrally; only this accountRef's DB record is
  // admitted through the explicit accountEnv channel.
  const hostBaseEnv = baseEnv || process.env;
  const runtime = options.runtimeScope || resolveNativeProviderRuntime(
    normalizedProvider,
    runtimeDir,
    hostBaseEnv,
    options
  );
  const accountEnv = runtime.accountEnv || {};
  prepareProviderRuntime(normalizedProvider, runtime.runtimeDir, hostBaseEnv, {
    path,
    fs,
    aiHomeDir: options.aiHomeDir,
    accountRef: options.accountRef,
    accountEnv,
    materializeAuth: runtime.projectionRequired,
    requireNativeAuth: !options.gateway && Object.keys(accountEnv).length === 0
  });
  if (normalizedProvider === 'gemini') Object.assign(extraEnv, geminiCliEndpointEnv(accountEnv));
  return buildProviderRuntimeEnv(normalizedProvider, runtime.runtimeDir, hostBaseEnv, {
    path,
    fs,
    aiHomeDir: options.aiHomeDir,
    accountRef: options.accountRef,
    accountEnv,
    extraEnv,
    // WebUI 原生会话直接连上游：同样过当前网络守卫（见 runtime/egress-launch-guard）。
    networkGuard: true
  });
}


module.exports = {
  loadAccountEnv,
  loadProviderAccountEnv,
  resolveNativeProviderRuntime,
  buildProviderEnv,
  geminiCliEndpointEnv
};
